function g = HS81_g(x)
g = zeros(5, 1);
g(1) = -3.0*x(1).^2.*(x(1).^3 + x(2).^3 + 1) + x(2).*x(3).*x(4).*x(5).*exp(x(1).*x(2).*x(3).*x(4).*x(5));
